Example 1: simple cancellation
func runSimple(ctx context.Context, client *redwood.Client) error {
    it := client.StreamIterator(ctx, &redwood.StreamRequest{Model: "rwd-2.1"})
    defer it.Close()
    for it.Next() {
        select {
        case <-ctx.Done():
            // ensure finalization path is exercised
            return ctx.Err()
        default:
        }
        token := it.Token()
        fmt.Print(token)
    }
    return it.Err()
}

